#!/usr/bin/env bash
# Generated by: Claude Opus 5.5
# Generation date: 2026-10-11
#
# Smoke-test an ollama image as an unprivileged user on a read-only root.
# Usage: smoke-test.sh <image> [ollama-model] [model-digest]
# Env:   OLLAMA_VERSION (expected Ollama version, plain digits)
set -euo pipefail

image=$1
model=${2:-}
digest=${3:-}
: "${OLLAMA_VERSION:?OLLAMA_VERSION must be set}"

port=11434
name="smoke-$$"
prefix="io.github.jmtovar.local-llm-images"

fail() { echo "::error::$*" >&2; exit 1; }

label() { docker inspect --format "{{ index .Config.Labels \"$1\" }}" "$image"; }

echo "== Labels and architecture"
[[ "$(label "$prefix.accelerator")" == cpu ]] || fail "accelerator label is not cpu"
[[ "$(label "$prefix.arch")" == amd64 ]] || fail "arch label is not amd64"
[[ "$(docker inspect --format '{{ .Architecture }}' "$image")" == amd64 ]] || fail "image architecture is not amd64"
[[ "$(label "$prefix.ollama.version")" == "$OLLAMA_VERSION" ]] || fail "ollama.version label mismatch"
if [[ -n "$model" ]]; then
  [[ "$(label "$prefix.model")" == "$model" ]] || fail "model label mismatch"
  [[ "$(label "$prefix.model.digest")" == "$digest" ]] || fail "model.digest label mismatch"
fi

# Same constraints as a read-only SIF run by a normal user
run_opts=(--user 65534:65534 --read-only --tmpfs /tmp --env HOME=/tmp --network host)
if [[ -z "$model" ]]; then
  # Writable by the unprivileged user, like a bind-mounted model store
  run_opts+=(--tmpfs /models:mode=1777)
fi

echo "== Libraries (ldd) and no GPU directories"
docker run --rm "${run_opts[@]}" --entrypoint /bin/sh "$image" -c '
  set -u
  rc=0
  for f in /usr/bin/ollama /usr/lib/ollama/llama-server /usr/lib/ollama/*.so*; do
    if ldd "$f" | grep -q "not found"; then
      echo "unresolved libraries in $f:"; ldd "$f" | grep "not found"; rc=1
    fi
  done
  ls /usr/lib/ollama/libggml-cpu-*.so >/dev/null 2>&1 || { echo "no CPU backend library"; rc=1; }
  # CPU build has no subdirectories; any one (cuda*, mlx_cuda*, vulkan*, rocm*) is a GPU backend
  dirs=$(find /usr/lib/ollama -mindepth 1 -type d)
  if [ -n "$dirs" ]; then echo "unexpected directories:"; echo "$dirs"; rc=1; fi
  exit $rc
' || fail "library check failed"

echo "== Server"
cleanup() { docker rm -f "$name" >/dev/null 2>&1 || true; }
trap cleanup EXIT
docker run -d --name "$name" "${run_opts[@]}" "$image" >/dev/null

ready=0
for _ in $(seq 60); do
  if curl -sf "http://127.0.0.1:$port/api/version" >/dev/null; then ready=1; break; fi
  # Stop waiting if the server has already exited
  [[ "$(docker inspect --format '{{ .State.Running }}' "$name")" == true ]] || break
  sleep 1
done
if [[ $ready -ne 1 ]]; then
  docker logs "$name" 2>&1 | tail -n 30
  fail "server did not start (see log above)"
fi

version_out=$(docker exec "$name" ollama --version)
echo "$version_out"
[[ "$version_out" == *"$OLLAMA_VERSION"* ]] || fail "ollama --version does not report $OLLAMA_VERSION"

list_out=$(docker exec "$name" ollama list) || fail "ollama list failed"
echo "$list_out"

if [[ -n "$model" ]]; then
  # ID column is the first 12 hex characters of the manifest digest
  id=${digest#sha256:}
  id=${id:0:12}
  awk -v m="$model" -v id="$id" '$1 == m && $2 == id { found = 1 } END { exit !found }' <<<"$list_out" \
    || fail "model $model with ID $id not listed"

  echo "== Prompt"
  reply=$(curl -sf --max-time 300 "http://127.0.0.1:$port/api/generate" \
    -d "$(jq -n --arg m "$model" '{model: $m, prompt: "Reply with: OK", stream: false, options: {num_predict: 8}}')") \
    || fail "generate request failed or timed out"
  jq -c '{response, thinking, done_reason, eval_count, prompt_eval_count}' <<<"$reply"
  # Reasoning models (e.g. Gemma 4) may spend the 8 tokens on "thinking"; either counts
  [[ -n "$(jq -r '(.response // "") + (.thinking // "")' <<<"$reply" | tr -d '[:space:]')" ]] \
    || fail "empty response"
fi

echo "Smoke test passed: $image"
